def asignar_al_primer_establecimiento(apps, schema_editor):
    """Los datos existentes (instalación de un solo colegio) quedan en el primer establecimiento."""
    Establecimiento = apps.get_model("academico", "Establecimiento")
    modelos = ["Curso", "Asignatura", "Estudiante", "Funcionario", "Comentario", "OpcionCatalogo"]
    hay_datos = any(apps.get_model("academico", m).objects.exists() for m in modelos) or \
        apps.get_model("academico", "Perfil").objects.exists()
    est = Establecimiento.objects.order_by("pk").first()
    if est is None:
        if not hay_datos:
            return
        est = Establecimiento.objects.create(nombre="Establecimiento educacional")
    for m in modelos:
        apps.get_model("academico", m).objects.filter(establecimiento__isnull=True).update(establecimiento=est)
    apps.get_model("academico", "Perfil").objects.filter(establecimiento__isnull=True).update(establecimiento=est)
    for e in Establecimiento.objects.all():
        if e.modulos in (None, []):
            e.modulos = ["curricular", "convivencia", "funcionarios"]
            e.save(update_fields=["modulos"])


Migration.operations.append(migrations.RunPython(asignar_al_primer_establecimiento, migrations.RunPython.noop))
